const operation = node.properties.operation.value;
let input = node.properties.input.value;
const path = node.properties.path?.value;
let value = node.properties.value?.value;
let mergeWith = node.properties.mergeWith?.value;
const prettyPrint = node.properties.prettyPrint?.value !== false;
const indent = node.properties.indent?.value || 2;

const resolveValue = (val) => {
  if (typeof val === 'string') {
    if (val === '{{data}}') return data;
    if (val.includes('{{data.')) {
      const match = val.match(/\{\{data\.([^}]+)\}\}/);
      if (match) {
        const pathParts = match[1].split('.');
        let result = data;
        for (const part of pathParts) {
          result = result?.[part];
        }
        return result;
      }
    }
  }
  return val;
};

input = resolveValue(input);

const getByPath = (obj, path) => {
  if (!path) return obj;
  const keys = path.replace(/\[(\d+)\]/g, '.$1').split('.');
  let result = obj;
  for (const key of keys) {
    if (result === null || result === undefined) return undefined;
    result = result[key];
  }
  return result;
};

const setByPath = (obj, path, value) => {
  if (!path) return obj;
  const keys = path.replace(/\[(\d+)\]/g, '.$1').split('.');
  let current = obj || {};
  for (let i = 0; i < keys.length - 1; i++) {
    const key = keys[i];
    if (!(key in current) || typeof current[key] !== 'object') {
      current[key] = {};
    }
    current = current[key];
  }
  current[keys[keys.length - 1]] = value;
  return obj;
};

helpers.log('Starting JSON Operations node');
helpers.log(`Operation: ${operation}`);

try {
  switch (operation) {
    case 'parse': {
      if (typeof input !== 'string') {
        helpers.error('Input must be a string for parse operation');
        return { path: 'error', error: 'Input must be a string for parse operation', input };
      }
      helpers.log(`Parsing JSON string (${input.length} characters)`);
      const parsed = JSON.parse(input);
      helpers.log('JSON parsed successfully');
      return { success: true, operation: 'parse', result: parsed };
    }
    case 'stringify': {
      helpers.log(`Stringifying JSON (prettyPrint: ${prettyPrint}, indent: ${indent})`);
      const replacer = (_k, v) => {
        if (typeof v === 'bigint') return v.toString();
        if (typeof v === 'function') return undefined;
        return v;
      };
      try {
        const stringified = prettyPrint ? JSON.stringify(input, replacer, indent) : JSON.stringify(input, replacer);
        helpers.log(`Created JSON string (${stringified.length} characters)`);
        return { success: true, operation: 'stringify', result: stringified, length: stringified.length };
      } catch (e) {
        helpers.error('JSON stringify failed:', e.message);
        return { path: 'error', error: 'JSON stringify failed', details: e.message };
      }
    }
    case 'get': {
      if (!path) {
        helpers.error('Path is required for get operation');
        return { path: 'error', error: 'Path is required for get operation' };
      }
      helpers.log(`Getting value at path: ${path}`);
      const result = getByPath(input, path);
      try { if (result !== undefined) helpers.log(`Value found: ${JSON.stringify(result)}`);} catch {}
      if (result === undefined) helpers.warn(`No value found at path: ${path}`);
      return { success: true, operation: 'get', path, result, found: result !== undefined };
    }
    case 'set': {
      if (!path) {
        helpers.error('Path is required for set operation');
        return { path: 'error', error: 'Path is required for set operation' };
      }
      helpers.log(`Setting value at path: ${path}`);
      let parsedValue = value;
      if (typeof value === 'string') {
        try { parsedValue = JSON.parse(value); helpers.log('Parsed value from JSON string'); }
        catch { helpers.log('Using value as string'); }
      }
      const result = JSON.parse(JSON.stringify(input || {}));
      setByPath(result, path, parsedValue);
      helpers.log('Value set successfully');
      return { success: true, operation: 'set', path, result };
    }
    case 'merge': {
      helpers.log('Merging objects');
      if (typeof mergeWith === 'string') {
        try { mergeWith = JSON.parse(mergeWith); helpers.log('Parsed merge object from JSON string'); }
        catch (e) { helpers.error('Invalid JSON in merge object:', e.message); return { path: 'error', error: 'Invalid JSON in merge object', details: e.message }; }
      }
      const deepMerge = (target, source, seen = new WeakMap()) => {
        if (source && typeof source === 'object') {
          if (seen.has(source)) return seen.get(source);
          const out = Array.isArray(target) ? [...(target || [])] : { ...(target || {}) };
          seen.set(source, out);
          for (const key in source) {
            const val = source[key];
            if (val && typeof val === 'object') {
              out[key] = deepMerge(out[key] || (Array.isArray(val) ? [] : {}), val, seen);
            } else {
              out[key] = val;
            }
          }
          return out;
        }
        return target;
      };
      try {
        const result = deepMerge(input || {}, mergeWith || {});
        helpers.log('Objects merged successfully');
        return { success: true, operation: 'merge', result };
      } catch (e) {
        helpers.error('Deep merge failed:', e.message);
        return { path: 'error', error: 'Deep merge failed', details: e.message };
      }
    }
    case 'keys': {
      if (typeof input !== 'object' || input === null) {
        helpers.error('Input must be an object for keys operation');
        return { path: 'error', error: 'Input must be an object for keys operation' };
      }
      const keys = Object.keys(input);
      helpers.log(`Extracted ${keys.length} keys from object`);
      return { success: true, operation: 'keys', result: keys, count: keys.length };
    }
    case 'values': {
      if (typeof input !== 'object' || input === null) {
        helpers.error('Input must be an object for values operation');
        return { path: 'error', error: 'Input must be an object for values operation' };
      }
      const values = Object.values(input);
      helpers.log(`Extracted ${values.length} values from object`);
      return { success: true, operation: 'values', result: values, count: values.length };
    }
    case 'validate': {
      helpers.log('Validating JSON');
      if (typeof input === 'string') {
        try { JSON.parse(input); helpers.log('JSON is valid'); return { success: true, operation: 'validate', valid: true, message: 'Valid JSON' }; }
        catch (e) { helpers.warn('JSON is invalid:', e.message); return { success: true, operation: 'validate', valid: false, error: e.message }; }
      } else {
        helpers.log('Input is already a JSON object');
        return { success: true, operation: 'validate', valid: true, message: 'Already a JSON object' };
      }
    }
    default:
      return { path: 'error', error: `Unknown operation: ${operation}` };
  }
} catch (error) {
  helpers.error('JSON operation failed:', error);
  return { error: error.message, operation, stack: error.stack };
}
